window.LD=window.LD||{};window.LD["replays"]={"rows":[{"t":"On the road","at":"the road between Frosthold and Whitepeak Pass","h":["h15"],"x":"A shadow passes over the road to Whitepeak Pass, huge and quick. Everyone on the road lies flat. Matt is the first one up, and the first one to laugh.","k":"road","id":"r88","d":32,"s":2,"sd":2,"imp":3,"score":30},{"t":"Met Mags Halloran","at":"the road between Carrbridge and Saltmarrow","h":["h11","h13","h2","h9"],"x":"Over the fire Mags Halloran tells Cade where the money is this month: The Wolf Den, if he is brave.","k":"road","id":"r92","d":32,"s":2,"sd":2,"imp":3,"score":30},{"t":"Stolen from the bank","at":"the Ashfen dyke","h":["h18"],"x":"Scout steals a bog eel from the bucket at the Ashfen dyke, and Morgan cannot stay angry at that tail.","k":"catch","id":"c22","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Stolen from the bank","at":"the runoff pool at the mouth of the Collapsed Mine","h":["h7","h17","h8","h5"],"x":"Corrine lands a blind cavefish in the runoff pool at the mouth of the Collapsed Mine and Bear lands on it. It is not clear who won.","k":"catch","id":"c23","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Rampart Hotpot","h":["h1"],"x":"The market in Carrbridge has a cook up from Thornwall today. Harry queues for some Rampart Hotpot on the strength of the smell alone. It fights back a little at the edges, where the crust went to…","tag":"tavern","k":"meal","id":"m47","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Varro Brothers' Spiced Bun","h":["h1"],"x":"Varro Brothers' Spiced Bun, eaten on an Ironhaven doorstep by Harry, who refuses to share. It leaves sugar on everything for the rest of the day. (6 copper)","tag":"tavern","k":"meal","id":"m48","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Forge-Bellows Pepper Pot","h":["h1"],"x":"Harry has a Forge-Bellows Pepper Pot at The Gilded Flagon and asks Madame Ostrava for the recipe. His favourite kind of thing. (2 silver 2 copper)","tag":"tavern","k":"meal","id":"m49","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Salamander Skewers","h":["h13"],"x":"A cart from Veldrock has come for market day in Carrbridge, selling Salamander Skewers. Cade buys one to see what the fuss is. They are still warm in the pack the next morning. (3 silver 9 copper)","tag":"tavern","k":"meal","id":"m50","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Grey Bread with Dripping","h":["h11"],"x":"A cart from Veldrock has come for market day in Carrbridge, selling some Grey Bread with Dripping. Joshua buys one to see what the fuss is. It drips in the right places. (4 copper)","tag":"tavern","k":"meal","id":"m51","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Skillet Berry Cobbler","at":"by the road to Ashfen","h":["h10","h14","h3"],"x":"Skillet Berry Cobbler by the road to Ashfen: Olivia is sure it's meant to smell like that. It isn't. Nobody sleeps well.","tag":"camp","k":"meal","id":"m52","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Skillet Berry Cobbler","at":"by the road to Saltmarrow","h":["h11","h9","h13","h2"],"x":"Joshua serves some Skillet Berry Cobbler by the road to Saltmarrow, and Keenan closes his eyes on the first mouthful. A favourite. It stains every spoon at the fire.","tag":"camp","k":"meal","id":"m53","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Ration-Bag Hash","at":"Cragtooth Warren","h":["h16","h4"],"x":"Allie smells some Ration-Bag Hash from the far side of the camp in Cragtooth Warren and comes at a run. Katie made it. It turns out better than the ration bag had any right to.","tag":"camp","k":"meal","id":"m54","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"the Pickaxe Rest","at":"the road between The Collapsed Mine and Veldrock","h":["h17","h5","h7","h8"],"x":"Troy buys a miners' breakfast at the Pickaxe Rest for 1 silver: a Smoked Sausage Coil, black bread and a mug of tea strong enough to float a nail.","k":"road","id":"r87","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"the Last Stove","at":"the road between Frosthold and Whitepeak Pass","h":["h15"],"x":"Matt warms both hands at the Last Stove while Hild Aaskov counts how many coats are drying on the line this time.","k":"road","id":"r89","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"the Scratched Stone","at":"the road between Carrbridge and Ironhaven","h":["h1","h12"],"x":"Jeff carves their name into the Scratched Stone, small, between a farmer and a dead king.","k":"road","id":"r90","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"the Leaning Mile","at":"the road between Ashfen and Carrbridge","h":["h18"],"x":"The Leaning Mile says it is one mile to Carrbridge and a dozen to Ashfen, though anyone can see the dyke from where Morgan stands.","k":"road","id":"r91","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"On the road","at":"the road between Ashfen and Carrbridge","h":["h10","h14","h3"],"x":"Olivia buys a hot bowl from a roadside stall on the road to Ashfen for a hungry beggar, paying 2 copper. The beggar says a long blessing over it.","k":"road","id":"r93","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Crown and Anchor: lost 4 silver","at":"Ironhaven","h":["h12"],"tag":"table","k":"table","id":"g10","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Crown and Anchor: lost 4 silver","at":"Ironhaven","h":["h1"],"tag":"table","k":"table","id":"g11","d":32,"s":2,"sd":2,"imp":1,"score":10},{"t":"Met the Muddy Boot Pack","at":"the road between Carrbridge and Ironhaven","h":["h11","h13","h2","h9"],"x":"Snaggle blocks Joshua's way with a rope and a wooden sign that reads TOL. Joshua pays one copper and is given a receipt made of bark.","k":"road","id":"r82","d":31,"s":2,"sd":1,"imp":3,"score":30},{"t":"Met Old Maudie","at":"the road between Carrbridge and Ironhaven","h":["h10","h14","h3"],"x":"Prudence and Clementine are right here, Old Maudie says to Ryan, but Tuesday has taken the chance to wander. A search begins.","k":"road","id":"r84","d":31,"s":2,"sd":1,"imp":3,"score":30},{"t":"Fishing","at":"by a stream on the road to Ashfen","h":["h18"],"x":"The line catches the neck of a bottle by a stream on the road to Ashfen. Morgan unrolls a letter signed by Troy and reads it twice.","k":"catch","id":"c21","d":31,"s":2,"sd":1,"imp":2,"score":20},{"t":"Cards for The Pack of Carrbridge, read by Allie","at":"camp in Cragtooth Warren","h":["h4","h16"],"x":"Nobody sleeps until Allie has read for The Pack of Carrbridge. The night before Cragtooth Warren, three cards: the Seven of Cups, the Two of Wands and the Knight of Cups. Some good, some not.","k":"reading","id":"r86","d":31,"s":2,"sd":1,"imp":2,"score":20},{"t":"Fried River Fish in a Paper Cone","h":["h1"],"x":"Harry buys some Fried River Fish in a Paper Cone in Carrbridge and eats it standing up. It comes wrapped in last week's tariff notices. (8 copper)","tag":"tavern","k":"meal","id":"m44","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"Walking-Cap Ragout","h":["h11"],"x":"Jolly Mott talks Joshua into some Walking-Cap Ragout at The Honest Toll. Good advice: it is rich, dark and only slightly mobile. (2 silver 1 copper)","tag":"tavern","k":"meal","id":"m45","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"Merchant's Honest Honey Cake","h":["h2"],"x":"Jolly Mott has written Merchant's Honest Honey Cake on the board at The Honest Toll in letters a foot high: dish of the week. Andrew orders it before sitting down. It is sticky in a way that follows…","tag":"tavern","k":"meal","id":"m46","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"Chess: Griffin v Amanda","at":"The Pickaxe & Pint","h":["h5","h17"],"x":"Amanda looks at the board, counts a queen missing, and tips the king on move 15.","tag":"chess","k":"night","id":"n40","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"the Ashfen ferry","at":"the road between Ashfen and Carrbridge","h":["h18"],"x":"Morgan sees an eye the size of a plate in the water beside the Ashfen ferry. Corve poles a little faster.","k":"road","id":"r77","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"On the road","at":"the road between Ashfen and Carrbridge","h":["h18"],"x":"Morgan claims a stick-sword from two squabbling children on the road to Ashfen for the good of the peace. The peace is a long way from restored.","k":"road","id":"r78","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"the Last Stove","at":"the road between Frosthold and Whitepeak Pass","h":["h15"],"x":"Matt reads the rumour board at the Last Stove, a hundred scraps pinned over each other, and picks out one that smells of truth: The Sunken Vault.","k":"road","id":"r79","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"the Whitepeak Cairn","at":"the road between Frosthold and Whitepeak Pass","h":["h15"],"x":"Matt stops at the Whitepeak Cairn, where a pair of walkers are stacking their stones in silence.","k":"road","id":"r80","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h16","h4"],"x":"Katie stops at the Last Dry Sock as Sergeant Ivo Ottoway hangs a fresh pair of socks on the pole with great ceremony.","k":"road","id":"r81","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"the Four Stones","at":"the road between Carrbridge and Ironhaven","h":["h11","h13","h2","h9"],"x":"At the Four Stones Andrew finds a flat stone, wipes it clean and sets it on the nearest heap with the rest.","k":"road","id":"r83","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"the Four Stones","at":"the road between Carrbridge and Ironhaven","h":["h10","h14","h3"],"x":"Mark follows the well-worn road from the Four Stones, which is well worn for a reason. It is smooth and kind.","k":"road","id":"r85","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"Coin Toss on the Bridge: won 522 silver","at":"Carrbridge","h":["h12"],"tag":"table","k":"table","id":"g9","d":31,"s":2,"sd":1,"imp":1,"score":10},{"t":"The Royal Shadows vs 2 Drakes and the Mimic King","r":"won","at":"Cragtooth Warren","h":["h9","h13","h11","h2"],"tag":"dungeon","k":"fight","id":"f82","d":30,"s":1,"sd":30,"imp":5,"score":65,"x":"At the bottom of Cragtooth Warren, The Royal Shadows put an end to 2 Drakes and the Mimic King. Cade's Aimed Shot saw to the Mimic King, Andrew's Sunder and Can't Stop Now did the rest, and Joshua…"},{"t":"On the road","at":"the road between The King's Road and Thornwall","h":["h17","h5","h7","h8"],"x":"A torn treasure map blows across the King's Road and wraps around Amanda's ankle. It is faded, but the Collapsed Mine is clearly marked.","k":"road","id":"r71","d":30,"s":1,"sd":30,"imp":3,"score":30},{"t":"Tench, 22 cm","at":"Wetfoot Ford","h":["h18"],"x":"The books show no Tench until today, when Morgan lands one at Wetfoot Ford.","k":"catch","id":"c18","d":30,"s":1,"sd":30,"imp":2,"score":20},{"t":"Arctic Char, 21 cm","at":"the tarn on Whitepeak Pass","h":["h15"],"x":"Matt adds a new name to the league's catch book at the tarn on Whitepeak Pass: Arctic Char, 21 cm, never taken before.","k":"catch","id":"c20","d":30,"s":1,"sd":30,"imp":2,"score":20},{"t":"Wraith-Chill Sorbet","at":"the Frosthold feast-day tables","h":["h15"],"x":"Matt is first in line for the Frosthold feast-day Wraith-Chill Sorbet, cooked from parts adventurers sold in town. It is cold enough to whisper. (8 copper)","tag":"tavern","k":"meal","id":"m42","d":30,"s":1,"sd":30,"imp":2,"score":20},{"t":"the Last Stove","at":"the road between Frosthold and Whitepeak Pass","h":["h15"],"x":"Matt tells the Last Stove its own best story of the road, and the room cheers and the stove, somehow, glows brighter.","k":"road","id":"r73","d":30,"s":1,"sd":30,"imp":2,"score":20},{"t":"Brown Trout, 27 cm","at":"the King's Road ford","h":["h10","h14","h3"],"x":"Olivia and Mark share a flask at the King's Road ford, a quiet hour, and a brown trout that nobody will admit was luck.","k":"catch","id":"c19","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"The Pack of Carrbridge vs 3 Goblin Archers","r":"won","at":"Cragtooth Warren","h":["h4","h16"],"tag":"dungeon","k":"fight","id":"f81","d":30,"s":1,"sd":30,"imp":1,"score":10,"x":"The Pack of Carrbridge, in fine spirits lately, cuts down 3 Goblin Archers in the tribute line on the bottom floor of Cragtooth Warren. Three of them fell to Katie's Cleave. Loot: 7 silver each, 3…"},{"t":"Ration-Bag Hash","at":"on the King's Road","h":["h7","h17","h8","h5"],"x":"Ration-Bag Hash on the King's Road: Troy says it's the best thing Corrine has ever made, and says so again in the morning. It turns out better than the ration bag had any right to.","tag":"camp","k":"meal","id":"m43","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"\"Haul Away for Captain Brine\" by the fire","at":"camp in Cragtooth Warren","h":["h13","h9","h11"],"x":"Cade leads \"Haul Away for Captain Brine\" and Keenan and Joshua stamp so hard the pot goes over. Supper is now part of the song.","tag":"song","k":"night","id":"n38","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"Checkers: Allie v Katie","at":"camp in Cragtooth Warren","h":["h4","h16"],"x":"Allie jumps the last piece and sits back, calm as a pond. Katie staked the Egg That Is Still Warm on the game, and Allie has it now.","tag":"checkers","k":"night","id":"n39","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h10","h14","h3"],"x":"Olivia crawls half a mile on hands and knees behind the marks and comes out where she started. The marks were a fallen log's.","tag":"hunt","k":"road","id":"r68","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h10","h14","h3"],"x":"The patient hunter eats well. Mark lets the rabbit hop into the open and takes it there. A ration.","tag":"hunt","k":"road","id":"r69","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h10","h14","h3"],"x":"Ryan looks at the family at the edge of the firelight and at the size of the supper, and says nothing. They move on without being asked. The meal tastes a little less of anything.","tag":"hunt","k":"road","id":"r70","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"the Lakeside Lamprey","at":"the road between The King's Road and Thornwall","h":["h17","h5","h7","h8"],"x":"Griffin fishes the Lakeside Lamprey's pond without a bet or a boast, and the water gives back a quiet hour and a few good fish.","k":"road","id":"r72","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"the Whitepeak Cairn","at":"the road between Frosthold and Whitepeak Pass","h":["h15"],"x":"Matt adds a stone to the Whitepeak Cairn, as every traveller to the pass does, and feels the weight of the ones beneath it.","k":"road","id":"r74","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"Wetfoot Ford","at":"the road between Bleakmarsh and Thornmere Ruins","h":["h18"],"x":"At Wetfoot Ford the fish are slow and the water is clear, and Morgan comes up with a catch and a very wet sleeve.","k":"road","id":"r75","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"Met the Off-Key Collective","at":"the road between Carrbridge and The King's Road","h":["h1","h12"],"x":"The Collective write a song about Jeff. It has seven verses, two choruses and five different endings, one for each of them.","k":"road","id":"r76","d":30,"s":1,"sd":30,"imp":1,"score":10},{"t":"Met Tansy Fell","at":"the road between The King's Road and Thornwall","h":["h17","h5","h7","h8"],"x":"Troy helps Tansy Fell clear a barn. The ferrets do the work. Troy holds the sack and the lamp, and is thanked like a partner.","k":"road","id":"r66","d":29,"s":1,"sd":29,"imp":3,"score":30},{"t":"Morgan vs a Bog Crawler","r":"won","at":"Bleakmarsh","h":["h18"],"tag":"road","k":"fight","id":"f79","d":29,"s":1,"sd":29,"imp":2,"score":20,"x":"On the road to Bleakmarsh, Morgan makes short work of a Bog Crawler. Morgan brought it to a close with Pounce. Loot: 4 chitin."},{"t":"The Rose Ledger vs a Bandit and a Bandit Archer","r":"won","at":"The King's Road","h":["h12","h1"],"tag":"wild","k":"fight","id":"f80","d":29,"s":1,"sd":29,"imp":2,"score":20,"x":"On the King's Road, the Rose Ledger squares up to a Bandit and a Bandit Archer and carries the day. Harry landed Poker Face on the bandit archer hard enough to hear from the back. Loot: 16 silver…"},{"t":"Chess: Allie v Katie","at":"camp in Cragtooth Warren","h":["h4","h16"],"x":"Move for move, it's the Sire's Trap, as the Sire of a Saltmarrow café laid it, giving up his queen for a mate by three small pieces, and someone at the fire says so. 7 moves. Allie mates Katie with…","tag":"chess","k":"night","id":"n37","d":29,"s":1,"sd":29,"imp":2,"score":20},{"t":"Silver Roach, 22 cm","at":"the King's Road ford","h":["h10","h14","h3"],"x":"Olivia reels in a silver roach at the King's Road ford, 22 cm of cheerful wriggling.","k":"catch","id":"c16","d":29,"s":1,"sd":29,"imp":1,"score":10},{"t":"Golden Carp, 39 cm","at":"the Thornwall millpond","h":["h8"],"x":"Troy unhooks a Golden Carp at the Thornwall millpond very slowly, in case it is a dream and the sudden movement ends it.","k":"catch","id":"c17","d":29,"s":1,"sd":29,"imp":1,"score":10},{"t":"The Pack of Carrbridge vs 2 Goblin Archers and a Kobold","r":"won","at":"Cragtooth Warren","h":["h4","h16"],"tag":"dungeon","k":"fight","id":"f77","d":29,"s":1,"sd":29,"imp":1,"score":10,"x":"Two Goblin Archers and a Kobold pick a fight with the Pack of Carrbridge in the new dig on the first floor of Cragtooth Warren and come off worst. Allie cast Endless Winter into the middle of them,…"},{"t":"The Black Pack vs a Bandit and a Bandit Archer","r":"won","at":"The King's Road","h":["h14","h3","h10"],"tag":"wild","k":"fight","id":"f78","d":29,"s":1,"sd":29,"imp":1,"score":10,"x":"On the King's Road, a Bandit and a Bandit Archer bar the way, briefly, before the Black Pack dispatches them. Olivia's Word of Unmaking finished the fight. Loot: 9 silver each, 1 bag of stolen…"},{"t":"Yeti-Bun","h":["h15"],"x":"Matt waits out the market-day crush in Frosthold for a Yeti-Bun, trading gossip with the queue. It is so soft it sighs when you bite it. (6 copper)","tag":"tavern","k":"meal","id":"m40","d":29,"s":1,"sd":29,"imp":1,"score":10},{"t":"Bramble-and-Barb Tart","h":["h5"],"x":"The dish of the week at The Sagging Beam is Bramble-and-Barb Tart. Griffin takes the hint. It leaves a purple mark on the lip that lasts till supper. (1 silver 4 copper)","tag":"tavern","k":"meal","id":"m41","d":29,"s":1,"sd":29,"imp":1,"score":10},{"t":"\"The Troll Counts Its Supper\" by the fire","at":"camp in Cragtooth Warren","h":["h13"],"x":"Cade launches into \"The Troll Counts Its Supper\", forgets the tune, and finishes it as a sort of speech. Boomer whines until it stops.","tag":"song","k":"night","id":"n36","d":29,"s":1,"sd":29,"imp":1,"score":10},{"t":"Cards for Morgan, read by Old Marrow","at":"a lean-to behind the undertaker's","h":["h18"],"x":"Morgan sits down across from Old Marrow at a lean-to behind the undertaker's. Three cards: the Ace of Wands, the Star and the King of Swords. A spread to sleep well on.","k":"reading","id":"r64","d":29,"s":1,"sd":29,"imp":1,"score":10},{"t":"On the road","at":"the road between Ashfen and Bleakmarsh","h":["h18"],"x":"Morgan finds leeches on both ankles and treats each with a spark. It is quick and nasty, and Morgan grins through it.","k":"road","id":"r65","d":29,"s":1,"sd":29,"imp":1,"score":10},{"t":"the Lakeside Lamprey","at":"the road between The King's Road and Thornwall","h":["h17","h5","h7","h8"],"x":"The Lakeside Lamprey's heron stalks along the porch rail as Griffin passes, studies his pack for fish, finds none, and bows anyway.","k":"road","id":"r67","d":29,"s":1,"sd":29,"imp":1,"score":10},{"t":"Matt vs the Raiders' Captain, a Bandit Archer and a Bandit","r":"lost","at":"Frosthold","h":["h15"],"tag":"road","k":"fight","id":"f75","d":28,"s":1,"sd":28,"imp":3,"score":30,"x":"On the walls of Frosthold, the Raiders' Captain, a Bandit Archer and a Bandit win the day, and Matt, overwhelmed, is left on the floor. Injured: Matt (bruised ribs)."},{"t":"Met Brother Aldo","at":"the road between Ashfen and The Ashveil Crypts","h":["h18"],"x":"Brother Aldo is too ill to walk, so Morgan shoulders the pack and most of the pilgrim as far as the next shelter.","k":"road","id":"r60","d":28,"s":1,"sd":28,"imp":3,"score":30},{"t":"Golden Grayling, 33 cm","at":"the King's Road ford","h":["h12","h1"],"x":"A first for the whole league: Jeff pulls a Golden Grayling at the King's Road ford and holds it up as proof.","k":"catch","id":"c15","d":28,"s":1,"sd":28,"imp":2,"score":20},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h17","h5","h7","h8"],"x":"Another crew was on this buck first, and Troy says so. In return they hand over a share of the kill without being asked. A ration.","tag":"hunt","k":"road","id":"r63","d":28,"s":1,"sd":28,"imp":2,"score":20},{"t":"The Pack of Carrbridge vs 2 Kobolds and a Goblin Archer","r":"won","at":"Cragtooth Warren","h":["h4","h16"],"tag":"dungeon","k":"fight","id":"f76","d":28,"s":1,"sd":28,"imp":1,"score":10,"x":"On the kobold in Cragtooth Warren, Katie finds an Egg That Is Still Warm and decides to keep it."},{"t":"Hedge Greens and Eggs","at":"on the King's Road","h":["h10","h14","h3"],"x":"Olivia cooks Hedge Greens and Eggs on the King's Road while the rest pretend to keep watch. They have eggs in them nobody asked too closely about.","tag":"camp","k":"meal","id":"m38","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"Skillet Berry Cobbler","at":"on the King's Road","h":["h7","h17","h8","h5"],"x":"Amanda smells some Skillet Berry Cobbler from the far side of the camp on the King's Road and comes at a run. Corrine made it. It stains every spoon at the fire.","tag":"camp","k":"meal","id":"m39","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"Chess: Olivia v Mark","at":"camp in The King's Road","h":["h10","h14"],"x":"Olivia reaches for a knight on move 26, moves the queen instead, and loses it. A queen on e1 ends it: Mark mates Olivia on move 28. Olivia sets the king back on its square and asks Mark to take…","tag":"chess","k":"night","id":"n33","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"\"The Troll Counts Its Supper\" by the fire","at":"camp in Cragtooth Warren","h":["h13","h9","h11"],"x":"Cade sings \"The Troll Counts Its Supper\" and loses the tune twice. Each time Keenan and Joshua hand it back. Waffles tilts its head at the wrong notes, every one.","tag":"song","k":"night","id":"n34","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"\"Parsley, Sage and Thyme\" by the fire","at":"camp in Cragtooth Warren","h":["h4"],"x":"Allie sings \"Parsley, Sage and Thyme\" three times, a little better each time. The crew pretend to be asleep by the third. Rufus yawns, loudly, in the second verse.","tag":"song","k":"night","id":"n35","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h11","h13","h2","h9"],"x":"Joshua reads the rumour wall of the Last Dry Sock while Sergeant Ivo Ottoway stamps a ticket for each reader. The freshest scrap speaks of Frostspire.","k":"road","id":"r57","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h1","h12"],"x":"An old hunter walks into the firelight, shares a pot of tea with Harry, and says the trail goes uphill from the stream. Then walks out again.","tag":"hunt","k":"road","id":"r58","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"the Wheel and Whistle","at":"the road between Carrbridge and The King's Road","h":["h10","h14","h3"],"x":"Ryan spots Big Ancel Pennyfeather at the Wheel and Whistle chalking the day's departures on a board almost as wide as the wall.","k":"road","id":"r59","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"the Shrine of Quiet Names","at":"the road between Ashfen and The Ashveil Crypts","h":["h18"],"x":"Morgan drops 1 copper in the dish at the Shrine of Quiet Names and lights a taper for the dead of Ashfen.","k":"road","id":"r61","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h17","h5","h7","h8"],"x":"Troy takes the long safe trail along the valley floor. It is slow, and it is dry, and he reads every bend of it.","tag":"hunt","k":"road","id":"r62","d":28,"s":1,"sd":28,"imp":1,"score":10},{"t":"Met the Fourth-Best Company","at":"the road between Ashfen and Carrbridge","h":["h10","h14","h3"],"x":"Mark hears Captain Mabb of the Fourth-Best Company claiming his last kill in a roadside inn. The story has more dragons in it.","k":"road","id":"r51","d":27,"s":1,"sd":27,"imp":3,"score":30},{"t":"On the road","at":"the road between Cragtooth Warren and Ironhaven","h":["h11","h13","h2","h9"],"x":"A bridal party sweeps Keenan up on the road to Ironhaven and carries him for a mile of dancing. Keenan leaves at the next gate with a ribbon and a cake.","k":"road","id":"r56","d":27,"s":1,"sd":27,"imp":3,"score":30},{"t":"Bog Eel, 73 cm","at":"the Ashfen ferry","h":["h10","h14","h3"],"x":"Olivia catches a bog eel at the Ashfen ferry, the league's very first, and the bank applauds like it was planned.","k":"catch","id":"c12","d":27,"s":1,"sd":27,"imp":2,"score":20},{"t":"The Rose Ledger vs a Bandit Archer and a Bandit","r":"won","at":"The King's Road","h":["h12","h1"],"tag":"wild","k":"fight","id":"f74","d":27,"s":1,"sd":27,"imp":2,"score":20,"x":"A Bandit Archer and a Bandit learn the hard way not to bother the Rose Ledger on the King's Road. Jeff closed it out with Aimed Shot on the bandit. Ask anyone who was there: Harry. Loot: 11 silver…"},{"t":"Stolen-Sausage Hotpot","at":"on the King's Road","h":["h7","h17","h8","h5"],"x":"Corrine makes some Stolen-Sausage Hotpot on the King's Road, mostly for Griffin, who knows it and is very pleased. It is the bandits' own beans, which feels right.","tag":"camp","k":"meal","id":"m37","d":27,"s":1,"sd":27,"imp":2,"score":20},{"t":"Cards for Ryan, read by Sabine Venn","at":"the toll-house parlour","h":["h3"],"x":"Sabine Venn lays three cards out for Ryan at the toll-house parlour: the Page of Wands, the King of Wands upside down and the Four of Wands. Sabine Venn hums over the cards and won't commit.","k":"reading","id":"r52","d":27,"s":1,"sd":27,"imp":2,"score":20},{"t":"Cards for Matt, read by Grandmother Skaldi","at":"a hut on the edge of the snowfield","h":["h15"],"x":"Matt sits down across from Grandmother Skaldi at a hut on the edge of the snowfield. Three cards: the Hierophant upside down, the Sun and the King of Wands. The spread can't make up its mind, and…","k":"reading","id":"r53","d":27,"s":1,"sd":27,"imp":2,"score":20},{"t":"The one that got away","at":"under Carrbridge","h":["h14"],"x":"Mark feels a mighty tug under Carrbridge and loses the fight. He thinks it was a brown trout.","k":"catch","id":"c13","d":27,"s":1,"sd":27,"imp":1,"score":10},{"t":"The one that got away","at":"the King's Road ford","h":["h7","h17","h8","h5"],"x":"Corrine loses a silver roach at the King's Road ford at the last second and spends the evening describing the exact angle.","k":"catch","id":"c14","d":27,"s":1,"sd":27,"imp":1,"score":10},{"t":"Twist-Bread on a Stick","at":"Cragtooth Warren","h":["h16","h4"],"x":"Katie cooks some Twist-Bread on a Stick in Cragtooth Warren. It has a scorch mark exactly where the cook looked away.","tag":"camp","k":"meal","id":"m36","d":27,"s":1,"sd":27,"imp":1,"score":10},{"t":"Chess: Katie v Allie","at":"camp in Cragtooth Warren","h":["h16","h4"],"x":"On move 7, Katie hangs the queen and pretends it was a sacrifice. Allie finds the mate on move 52, a queen doing the honours. The very first game between Allie and Katie is over, and it has set the…","tag":"chess","k":"night","id":"n31","d":27,"s":1,"sd":27,"imp":1,"score":10},{"t":"\"The Feathered Cap\" by the fire","at":"camp in The King's Road","h":["h1"],"x":"Harry tunes the Silver Lute by ear, then plays a song of their own so cleanly the strings seem to sing it on their own. Nugget howls along on the chorus, a beat behind and very proud of it.","tag":"song","k":"night","id":"n32","d":27,"s":1,"sd":27,"imp":1,"score":10},{"t":"On the road","at":"the road between Ashfen and Carrbridge","h":["h10","h14","h3"],"x":"Ryan takes a pilgrim's heavy bundle on the road to Carrbridge and finds it full of stones. The pilgrim says it is the whole point.","k":"road","id":"r50","d":27,"s":1,"sd":27,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h1","h12"],"x":"Harry walks past the blaze without a glance and finds the day's first fresh sign by an hour of plain looking.","tag":"hunt","k":"road","id":"r54","d":27,"s":1,"sd":27,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h1","h12"],"x":"A clutch of eggs lies in the grass, unwatched. Jeff takes only what a fox would, and puts the rest back under the leaves. A ration, wrapped in moss.","tag":"hunt","k":"road","id":"r55","d":27,"s":1,"sd":27,"imp":1,"score":10},{"t":"The hunters of Thulgarath vs Thulgarath the Polite Destroyer","r":"won","at":"Thornwall","h":["h7","h8","h5","h17"],"tag":"hyper","k":"fight","id":"f72","d":26,"s":1,"sd":26,"imp":5,"score":279,"x":"Thulgarath the Polite Destroyer is dead! It falls to Corrine, Troy, Griffin, Amanda in Thornwall, and Corrine carves the Gutter Spoon from what's left."},{"t":"The Pack of Carrbridge vs a Bandit Archer","r":"won","at":"The King's Road","h":["h4","h16"],"tag":"road","k":"fight","id":"f73","d":26,"s":1,"sd":26,"imp":2,"score":20,"x":"Allie takes the worst of it as the Pack of Carrbridge dispatches a Bandit Archer on the road to Cragtooth Warren. The fight turned on Allie's Frost Shard. Katie's Berserk did the work nobody saw.…"},{"t":"Troll Haunch","at":"on the King's Road","h":["h1","h12"],"x":"Harry makes a Troll Haunch on the King's Road and nobody talks while it's eaten. It has to be carved faster than it heals.","tag":"camp","k":"meal","id":"m35","d":26,"s":1,"sd":26,"imp":2,"score":20},{"t":"Checkers: Cade v Andrew","at":"camp in Cragtooth Warren","h":["h13","h2"],"x":"Andrew sighs happily, opens the Slate and Chalk Checkers, and gets the board ready for Cade. Cade watches Andrew jump the last piece and applauds with only a little teeth. Cade lost the bet and now…","tag":"checkers","k":"night","id":"n29","d":26,"s":1,"sd":26,"imp":2,"score":20},{"t":"On the road","at":"the road between Cragtooth Warren and Ironhaven","h":["h16","h4"],"x":"Allie beats out a stack fire beside the road to Cragtooth Warren with a wet coat and a lot of language. The farm is saved, and the farmer loads her down with bread.","k":"road","id":"r45","d":26,"s":1,"sd":26,"imp":2,"score":20},{"t":"On the road","at":"the road between Ashfen and Carrbridge","h":["h10","h14","h3"],"x":"Mark waves everyone off the road to Carrbridge and clears a lane while the cart rolls on by. No one is hurt, and the barrels end up in a hedge, whole, to a round of applause.","k":"road","id":"r49","d":26,"s":1,"sd":26,"imp":2,"score":20},{"t":"Knucklebones: won 1140 silver","at":"Frosthold","h":["h15"],"tag":"table","k":"table","id":"g8","d":26,"s":1,"sd":26,"imp":2,"score":20,"x":"Matt throws a perfect set and the hearthside roars, paying 11 gold pieces and 4 silver."},{"t":"Varro Brothers' Spiced Bun","h":["h16"],"x":"The dish of the week at The Gilded Flagon is Varro Brothers' Spiced Bun. Katie takes the hint. It is still warm and smells of cinnamon and grudge. (6 copper)","tag":"tavern","k":"meal","id":"m31","d":26,"s":1,"sd":26,"imp":1,"score":10},{"t":"Fried River Fish in a Paper Cone","h":["h1"],"x":"Harry hands over 8 copper in Carrbridge and gets some Fried River Fish in a Paper Cone in return. A fair trade. It comes in a cone of somebody's unpaid toll notice.","tag":"tavern","k":"meal","id":"m32","d":26,"s":1,"sd":26,"imp":1,"score":10},{"t":"Toasted Cheese Trenchers","at":"by the road to Carrbridge","h":["h10","h14","h3"],"x":"Olivia lays out Toasted Cheese Trenchers by the road to Carrbridge on a flat stone, like a proper table. They drip cheese off the edge of the bread in the best way.","tag":"camp","k":"meal","id":"m33","d":26,"s":1,"sd":26,"imp":1,"score":10},{"t":"Ration-Bag Hash","at":"Cragtooth Warren","h":["h16","h4"],"x":"Ration-Bag Hash in Cragtooth Warren, by Katie. Allie goes very quiet, which is how Allie says thank you for her favourite.","tag":"camp","k":"meal","id":"m34","d":26,"s":1,"sd":26,"imp":1,"score":10},{"t":"\"Redcrag Morning\" by the fire","at":"camp in The King's Road","h":["h5","h17","h8","h7"],"x":"Griffin sings \"Redcrag Morning\" like a war cry, which is roughly what it sounds like. Amanda, Troy and Corrine charge in on the chorus. Bear tilts its head at the wrong notes, every one.","tag":"song","k":"night","id":"n30","d":26,"s":1,"sd":26,"imp":1,"score":10},{"t":"the Lakeside Lamprey","at":"the road between The King's Road and Thornwall","h":["h17","h5","h7","h8"],"x":"Peg Marlow calls out the day's fish from the Lakeside Lamprey's porch, and Corrine hears the list twice before reaching the door.","k":"road","id":"r46","d":26,"s":1,"sd":26,"imp":1,"score":10},{"t":"the Wheel and Whistle","at":"the road between Carrbridge and The King's Road","h":["h1","h12"],"x":"Jeff passes the Wheel and Whistle, where a stable lad whistles the horses to their stalls and one actually goes.","k":"road","id":"r47","d":26,"s":1,"sd":26,"imp":1,"score":10},{"t":"the Leaning Mile","at":"the road between Ashfen and Carrbridge","h":["h10","h14","h3"],"x":"Mark finds a clear patch on the back of the Leaning Mile and carves a name there, small and straight against the lean.","k":"road","id":"r48","d":26,"s":1,"sd":26,"imp":1,"score":10},{"t":"the Shrine of Quiet Names","at":"the road between Ashfen and The Ashveil Crypts","h":["h10","h14","h3"],"x":"Olivia leaves 1 copper in the dish at the Shrine of Quiet Names and whispers the name of someone gone.","k":"road","id":"r52","d":26,"s":1,"sd":26,"imp":1,"score":10},{"t":"Chess: Mark v Olivia","at":"The Damp Lantern","h":["h14","h10"],"x":"Olivia loses the queen on move 12 and stares at the empty square as if it might come back. Olivia looks at the board, counts a queen missing, and tips the king on move 14. A streak of five has made…","tag":"chess","k":"night","id":"n27","d":25,"s":1,"sd":25,"imp":3,"score":30},{"t":"Met Doctor Fabian Loom","at":"the road between Carrbridge and Ironhaven","h":["h16","h4"],"x":"Allie agrees to try the Doctor's famous tonic. It is mostly honey and fear, and does them no harm whatever.","k":"road","id":"r37","d":25,"s":1,"sd":25,"imp":3,"score":30},{"t":"The Royal Shadows vs 2 Goblin Archers, a Kobold and a Kobold Slinger","r":"won","at":"Cragtooth Warren","h":["h9","h13","h11","h2"],"tag":"dungeon","k":"fight","id":"f71","d":25,"s":1,"sd":25,"imp":2,"score":20,"x":"Riding a good week, the Royal Shadows defeat 2 Goblin Archers, a Kobold and a Kobold Slinger in the slingers' gallery on the first floor of Cragtooth Warren. Keenan's Flame Jet took down two of them…"},{"t":"Cards: Harry v Bandit","at":"the road to Carrbridge","h":["h1"],"x":"The bandit drops into the road, points at Harry and says, you, Crooked Cards, one round, loser pays. The bandit has lost, and the bandit knows it, and Bandit's Marked Card is held out with great…","tag":"cards","k":"night","id":"n26","d":25,"s":1,"sd":25,"imp":2,"score":20},{"t":"Cards for Amanda, read by Aunt Crumb","at":"the back of the pie shop","h":["h17"],"x":"Amanda sits down across from Aunt Crumb at the back of the pie shop. Three cards: the Wheel of Fortune, the Two of Pentacles upside down and the Seven of Wands. One card for, one against, one…","k":"reading","id":"r43","d":25,"s":1,"sd":25,"imp":2,"score":20},{"t":"On the road","at":"the road between Ashfen and The Ashveil Crypts","h":["h10","h14","h3"],"x":"Olivia rights a signpost on the road to Ashfen that points confidently at a ditch. A passing pedlar is glad of it.","k":"road","id":"r40","d":25,"s":1,"sd":25,"imp":2,"score":20},{"t":"Fried River Fish in a Paper Cone","h":["h16"],"x":"Katie eats some Fried River Fish in a Paper Cone on the move through Carrbridge, getting crumbs on everything. It comes in a cone of somebody's unpaid toll notice. (8 copper)","tag":"tavern","k":"meal","id":"m28","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"Toll-Bridge Fritters","h":["h1"],"x":"Harry stops for Toll-Bridge Fritters in Carrbridge. They are worth the toll on their own. (6 copper)","tag":"tavern","k":"meal","id":"m29","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"Ration-Bag Hash","at":"Cragtooth Warren","h":["h11","h9","h13","h2"],"x":"Cade scrapes the pot clean of Joshua's Ration-Bag Hash in Cragtooth Warren and looks round for more. Cade's favourite kind of thing.","tag":"camp","k":"meal","id":"m30","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"Chess: Griffin v Amanda","at":"The Sagging Beam","h":["h5","h17"],"x":"Griffin's queen goes for a walk on move 6 and doesn't come back. Move 37: Amanda says 'mate' very quietly, and points at the queen. The first game ends and the tally begins, Amanda on one side and…","tag":"chess","k":"night","id":"n28","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"On the road","at":"the road between Carrbridge and Ironhaven","h":["h16","h4"],"x":"Allie buys a spoonful of honey from a beekeeper's stall for a copper, and then a second spoonful on credit.","k":"road","id":"r38","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"the Four Stones","at":"the road between Carrbridge and Ironhaven","h":["h1","h12"],"x":"Harry adds a pebble at the Four Stones and watches the heap by the nearest pillar slide a little and settle.","k":"road","id":"r39","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"Met the Off-Key Collective","at":"the road between Hollowood and Thornwall","h":["h17","h5","h7","h8"],"x":"Corrine is made the judge of a contest between the Collective and a pair of drunken crows. The crows have the better voices.","k":"road","id":"r41","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"the Shrine of the Footsore Saint","at":"the road between Hollowood and Thornwall","h":["h17","h5","h7","h8"],"x":"Troy pays 1 copper at the Shrine of the Footsore Saint and sits on the low stone, easing a boot off with a groan.","k":"road","id":"r42","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"the Whitepeak Cairn","at":"the road between Frosthold and Whitepeak Pass","h":["h15"],"x":"Matt lifts a boulder for the Whitepeak Cairn and drops it on a foot, and the cairn is forgiven, but only just.","k":"road","id":"r44","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"Crown and Anchor: broke even","at":"Ironhaven","h":["h12"],"tag":"table","k":"table","id":"g6","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"Knucklebones: lost 500 silver","at":"Frosthold","h":["h15"],"tag":"table","k":"table","id":"g7","d":25,"s":1,"sd":25,"imp":1,"score":10},{"t":"the Snow Lamp","at":"the road between Frostspire and Whitepeak Pass","h":["h15"],"x":"An old pilgrim at the Snow Lamp tells Matt that the flame was lit by the first traveller to cross this pass, and has never gone out since. Matt leaves 2 copper to keep it.","k":"road","id":"r31","d":24,"s":1,"sd":24,"imp":3,"score":30},{"t":"On the road","at":"the road between The Greenwood and Hollowood","h":["h7"],"x":"A raven beside the road to Hollowood tells Corrine something about Goblin Camp in a voice like an old man, and flies off before Corrine can ask a thing.","k":"road","id":"r32","d":24,"s":1,"sd":24,"imp":3,"score":30},{"t":"Mere Carp, 77 cm","at":"the Wolfwater ferry","h":["h5","h17","h8"],"x":"Griffin lands a mere carp at the Wolfwater ferry, the first the league has ever seen. The anglers will want to hear about it.","k":"catch","id":"c11","d":24,"s":1,"sd":24,"imp":2,"score":20},{"t":"Corrine vs a Wolf","r":"won","at":"The Greenwood","h":["h7"],"tag":"road","k":"fight","id":"f70","d":24,"s":1,"sd":24,"imp":2,"score":20,"x":"Corrine defeats a Wolf on the road to Hollowood without much fuss. The wolf was already dying of Corrine's Thorn Whip before it knew it. Loot: 1 pelt, 1 fang, a wolf haunch."},{"t":"Cards: Troy v Bandit","at":"the road to Hollowood","h":["h8"],"x":"The bandit steps out on the road to Hollowood with a hopeful expression and a well-worn set of Crooked Cards, and nobody can quite bring themselves to draw a blade. The bandit reads the final board…","tag":"cards","k":"night","id":"n23","d":24,"s":1,"sd":24,"imp":2,"score":20},{"t":"Chess: Olivia v Mark","at":"camp in The Ashveil Crypts","h":["h10","h14"],"x":"On move 9, Olivia hangs the queen. Mark tries not to smile, and fails. Olivia plays on a queen down for a while, then tips the king on move 26. Olivia has studied the loss for a whole minute and is…","tag":"chess","k":"night","id":"n24","d":24,"s":1,"sd":24,"imp":2,"score":20},{"t":"Crown and Anchor: lost 948 silver","at":"Ironhaven","h":["h12"],"tag":"table","k":"table","id":"g4","d":24,"s":1,"sd":24,"imp":2,"score":20,"x":"Clerk Odalric writes 94 silver in Jeff's account and underlines it in red."},{"t":"Not a fish","at":"the Mossy Lantern","h":["h7"],"x":"Corrine lands a hat at the Mossy Lantern, and the fish nearby seem to be enjoying the show.","k":"catch","id":"c10","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"Forest-Floor Salad","at":"judging the Hollowood cooks' feud","h":["h17"],"x":"Nettle the herb-wife and Ranger Holt have argued about whether a salad counts as supper for years. In Hollowood, Amanda is handed a spoon by each and told to settle it. Amanda picks Ranger Holt. (1…","tag":"tavern","k":"meal","id":"m24","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"Rat-on-a-Stick","h":["h17"],"x":"Rat-on-a-Stick at The Watching Oak: Amanda cleans the plate. It is better than it has any right to be. (1 silver 5 copper)","tag":"tavern","k":"meal","id":"m25","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"Hammerhand Mixed Grill","h":["h1"],"x":"Harry has a Hammerhand Mixed Grill at The Gilded Flagon and sends compliments to Madame Ostrava. It comes on a shield with a dent in it that has a story. (3 silver 5 copper)","tag":"tavern","k":"meal","id":"m26","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"Rat-on-a-Stick","h":["h7","h8","h5"],"x":"Corrine, Troy and Griffin take the corner table at The Watching Oak and work through a Rat-on-a-Stick together. It is the kind of thing nobody admits to liking, then has two. (1 silver 5 copper each)","tag":"tavern","k":"meal","id":"m27","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"\"Brother Bellringer\" by the fire","at":"The Gilded Flagon","h":["h1"],"x":"Harry plays \"Brother Bellringer\" at The Gilded Flagon, and the laughs come right where they should. 9 silver 4 copper in the hat and a drink nobody ordered.","tag":"song","k":"night","id":"n25","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h12"],"x":"The thief outruns Jeff across a field, but drops one boot every ten paces. Jeff gathers them all, bitterly, on the way home.","k":"road","id":"r29","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h11","h13","h2","h9"],"x":"At dawn Sergeant Ivo Ottoway drags Joshua out to the Last Dry Sock's yard for a drill, and then, satisfied, gives out breakfast to all who survived it.","k":"road","id":"r30","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"the Crooked Kettle","at":"the road between Hollowood and The Wolf Den","h":["h17","h5","h8"],"x":"Troy smells woodsmoke and bay leaf a long way before the Crooked Kettle comes into view among the trees.","k":"road","id":"r33","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"the Wheel and Whistle","at":"the road between Carrbridge and The King's Road","h":["h16","h4"],"x":"Big Ancel Pennyfeather sets a trencher in front of Allie for 1 silver. The gravy comes in a boat, and the boat in a second boat.","k":"road","id":"r34","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"On the road","at":"the road between Carrbridge and The King's Road","h":["h16","h4"],"x":"The elephant on the King's Road has a hat. Allie says nothing about it. The elephant's keeper, a small old woman, says nothing about Allie's hat either, and they part friends.","k":"road","id":"r35","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h1"],"x":"Harry spots the sock sign at the Last Dry Sock, damp at one end and flapping hopefully at the other.","k":"road","id":"r36","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"Crown and Anchor: won 138 silver","at":"Ironhaven","h":["h1"],"tag":"table","k":"table","id":"g5","d":24,"s":1,"sd":24,"imp":1,"score":10},{"t":"The Ford Ghost got away","at":"the King's Road ford","h":["h16","h4"],"x":"Katie held The Ford Ghost at the King's Road ford for twenty heartbeats. The line did not. The legend swims on.","k":"catch","id":"c8","d":23,"s":1,"sd":23,"imp":3,"score":30},{"t":"The Green Hammers vs 4 Kobolds","r":"won","at":"Cragtooth Warren","h":["h1","h12"],"tag":"dungeon","k":"fight","id":"f68","d":23,"s":1,"sd":23,"imp":2,"score":20,"x":"In the kobold nursery on the bottom floor of Cragtooth Warren, 4 Kobolds get in the Green Hammers' way, briefly. Ask anyone when it turned: Harry's Arc Lightning. Jeff dropped four of them, Shot…"},{"t":"Nothing bit","at":"Greenwood Mere","h":["h7"],"x":"Corrine waits for the moon to do something helpful at Greenwood Mere. It does not.","k":"catch","id":"c9","d":23,"s":1,"sd":23,"imp":1,"score":10},{"t":"The Pack of Carrbridge vs a Bandit","r":"won","at":"The King's Road","h":["h4","h16"],"tag":"wild","k":"fight","id":"f69","d":23,"s":1,"sd":23,"imp":1,"score":10,"x":"On the King's Road, the Pack of Carrbridge squares up to a Bandit and carries the day. Allie wove Glacial Wall over the others and they felt it. Look past the blows: Allie's Ice Wall was the…"},{"t":"Chess: Olivia v Mark","at":"camp in The Ashveil Crypts","h":["h10","h14"],"x":"Olivia gives the queen away for nothing on move 11, and the camp gasps. Mark finds the mate on move 18, a queen doing the honours. The stake was breakfast, and Olivia will be stirring the pot at dawn.","tag":"chess","k":"night","id":"n20","d":23,"s":1,"sd":23,"imp":1,"score":10},{"t":"Checkers: Katie v Allie","at":"camp in The King's Road","h":["h16","h4"],"x":"Katie resigns with a bow, a sigh and a promise. The very first game between Allie and Katie is over, and it has set the tone. Stake paid: Katie will take the first watch while everyone else goes to…","tag":"checkers","k":"night","id":"n21","d":23,"s":1,"sd":23,"imp":1,"score":10},{"t":"\"Redcrag Morning\" by the fire","at":"camp in The Wolf Den","h":["h5","h8"],"x":"Griffin stands on a log for the big finish of \"Redcrag Morning\", and the log has other ideas.","tag":"song","k":"night","id":"n22","d":23,"s":1,"sd":23,"imp":1,"score":10},{"t":"Hunting in The Greenwood","at":"The Greenwood","h":["h7"],"x":"Corrine ties a strip of cloth to the nearest branch to mark the spot, reads which way the animal was heading, and goes round to meet it.","tag":"hunt","k":"road","id":"r26","d":23,"s":1,"sd":23,"imp":1,"score":10},{"t":"Hunting in The Greenwood","at":"The Greenwood","h":["h7"],"x":"Corrine waits and the quarry does not come. After an hour, a gust of wind turns, and it knows. It is gone.","tag":"hunt","k":"road","id":"r27","d":23,"s":1,"sd":23,"imp":1,"score":10},{"t":"On the road","at":"the road between Cragtooth Warren and Ironhaven","h":["h11","h13","h2","h9"],"x":"Andrew limps in new boots on the road to Ironhaven, and Joshua calls a halt to look at the blisters. The band rests on a bank while Andrew soaks in a stream, and the walk after is lighter.","k":"road","id":"r28","d":23,"s":1,"sd":23,"imp":1,"score":10},{"t":"Silver Roach, 12 cm","at":"the King's Road ford","h":["h16","h4"],"x":"A first for the whole league: Katie pulls a silver roach at the King's Road ford and holds it up as proof.","k":"catch","id":"c5","d":22,"s":1,"sd":22,"imp":2,"score":20},{"t":"Brown Trout, 22 cm","at":"the King's Road ford","h":["h16","h4"],"x":"The books show no Brown Trout until today, when Katie lands one at the King's Road ford.","k":"catch","id":"c7","d":22,"s":1,"sd":22,"imp":2,"score":20},{"t":"The Green Hammers vs a Cave Troll","r":"won","at":"Cragtooth Warren","h":["h1","h12"],"tag":"dungeon","k":"fight","id":"f66","d":22,"s":1,"sd":22,"imp":2,"score":20,"x":"It's a Cave Troll against the Green Hammers in the troll's hollow on the bottom floor of Cragtooth Warren, and it isn't close. Harry's Poker Face had the cave troll briefly confused about whose side…"},{"t":"\"The Star-Counter's Tune\" by the fire","at":"camp in Cragtooth Warren","h":["h1"],"x":"Harry plays \"The Star-Counter's Tune\" by the fire, and for once every note lands. They do it again to be sure.","tag":"song","k":"night","id":"n19","d":22,"s":1,"sd":22,"imp":2,"score":20},{"t":"Hunting in The Greenwood","at":"The Greenwood","h":["h7"],"x":"Corrine has the doe in a clear line, sees the fawn behind it, and lowers the bow. A hunter's choice and nobody's rule. The two walk on, light on their feet.","tag":"hunt","k":"road","id":"r25","d":22,"s":1,"sd":22,"imp":2,"score":20},{"t":"Perch, 28 cm","at":"Greenwood Mere","h":["h7"],"x":"Corrine has a nibble, then a tug, then a perch at Greenwood Mere. The order matters to her.","k":"catch","id":"c6","d":22,"s":1,"sd":22,"imp":1,"score":10},{"t":"The Pack of Carrbridge vs 2 Bandit Archers and a Bandit","r":"won","at":"The King's Road","h":["h4","h16"],"tag":"wild","k":"fight","id":"f67","d":22,"s":1,"sd":22,"imp":1,"score":10,"x":"Two Bandit Archers and a Bandit learn the hard way not to bother the Pack of Carrbridge on the King's Road. Allie's Arc Lightning went off among them; two bandit archers stayed down. Loot: 23 silver…"},{"t":"\"The Green Sleeve\" by the fire","at":"camp in The Ashveil Crypts","h":["h3","h14","h10"],"x":"Ryan leads \"The Green Sleeve\" with more courage than pitch, and Mark and Olivia love it for that. Clementine leaves at the first note.","tag":"song","k":"night","id":"n16","d":22,"s":1,"sd":22,"imp":1,"score":10},{"t":"\"By the Light of the Moon\" by the fire","at":"camp in Cragtooth Warren","h":["h13"],"x":"Cade sings \"By the Light of the Moon\" to the words of a different song. It almost works.","tag":"song","k":"night","id":"n17","d":22,"s":1,"sd":22,"imp":1,"score":10},{"t":"\"Constable Damp's Complaint\" by the fire","at":"camp in The Wolf Den","h":["h5","h8"],"x":"\"Constable Damp's Complaint\" by Griffin: wobbly in the middle and grand at the end, with Troy carrying the chorus.","tag":"song","k":"night","id":"n18","d":22,"s":1,"sd":22,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h16","h4"],"x":"Allie leaves the nest alone, steps wide around it and watches the hen circle back. The woods are a larder, but not that one.","tag":"hunt","k":"road","id":"r22","d":22,"s":1,"sd":22,"imp":1,"score":10},{"t":"Hunting in The King's Road","at":"The King's Road","h":["h16","h4"],"x":"The push comes too soon. The quarry that was a hundred paces off is a thousand paces off by the time Allie has found her feet.","tag":"hunt","k":"road","id":"r23","d":22,"s":1,"sd":22,"imp":1,"score":10},{"t":"Hunting in The Greenwood","at":"The Greenwood","h":["h7"],"x":"Corrine's arrow catches a hare and it gets away into the grass. Corrine waits an hour for it to lie down and stiffen, and follows the blood afterward. Slow work and the right kind. A ration.","tag":"hunt","k":"road","id":"r24","d":22,"s":1,"sd":22,"imp":1,"score":10},{"t":"The Royal Shadows vs 3 Kobolds and a Giant Bat","r":"won","at":"Cragtooth Warren","h":["h9","h13","h11","h2"],"tag":"dungeon","k":"fight","id":"f59","d":21,"s":1,"sd":21,"imp":3,"score":30,"x":"Cade hits hardest as the Royal Shadows see off 3 Kobolds and a Giant Bat in the sentry hole on the first floor of Cragtooth Warren: one Volley caught three of them at once. Whenever it looked bad,…"},{"t":"The Royal Shadows vs 2 Giant Bats and 2 Goblin Archers","r":"won","at":"Cragtooth Warren","h":["h9","h13","h11","h2"],"tag":"dungeon","k":"fight","id":"f60","d":21,"s":1,"sd":21,"imp":2,"score":20,"x":"Two Giant Bats and 2 Goblin Archers fall to the Royal Shadows in the new dig on the first floor of Cragtooth Warren. One Arcane Torrent from Joshua and two of them were on the ground. Joshua kept…"},{"t":"The Green Hammers vs 2 Kobolds and a Kobold Slinger","r":"won","at":"Cragtooth Warren","h":["h1","h12"],"tag":"dungeon","k":"fight","id":"f61","d":21,"s":1,"sd":21,"imp":2,"score":20,"x":"Jeff quietly pockets an extra 8 silver while The Green Hammers count the rest. Nobody notices."},{"t":"Tidal Riders vs 2 Dire Wolves and 2 Wolves","r":"won","at":"The Wolf Den","h":["h17","h8","h5"],"tag":"dungeon","k":"fight","id":"f62","d":21,"s":1,"sd":21,"imp":2,"score":20,"x":"In the moon-howl hollow on the first floor of the Wolf Den, 2 Dire Wolves and 2 Wolves get in Tidal Riders' way, briefly. Amanda put everything into one Drain Life, and the dire wolf reeled. Loot: 5…"},{"t":"Tidal Riders vs 3 Dire Wolves","r":"won","at":"The Wolf Den","h":["h17","h8","h5"],"tag":"dungeon","k":"fight","id":"f63","d":21,"s":1,"sd":21,"imp":2,"score":20,"x":"Troy keeps the good chair at The Watching Oak for Amanda. Amanda keeps the last of the stew for Troy. Friends, then."},{"t":"Corrine vs a Bandit","r":"won","at":"The Greenwood","h":["h7"],"tag":"road","k":"fight","id":"f65","d":21,"s":1,"sd":21,"imp":2,"score":20,"x":"On the road to the Greenwood, a Bandit gets in Corrine's way, briefly. Before Corrine's Thorn Whip it could have gone either way. Loot: 16 silver, a string of bandit sausages."},{"t":"Cards for Katie, read by Allie","at":"camp in The King's Road","h":["h4","h16"],"x":"Allie reads the Good Dog Tarot for Katie on a folded cloak: the Five of Cups, the Seven of Wands and the Seven of Swords upside down. Allie says it could go either way.","k":"reading","id":"r21","d":21,"s":1,"sd":21,"imp":2,"score":20},{"t":"Tidal Riders vs a Dire Wolf","r":"won","at":"The Wolf Den","h":["h17","h8","h5"],"tag":"dungeon","k":"fight","id":"f64","d":21,"s":1,"sd":21,"imp":1,"score":10,"x":"Tidal Riders, in fine spirits lately, defeat a Dire Wolf in the kill ground on the first floor of the Wolf Den. Amanda landed Drain Life on the dire wolf hard enough to hear from the back. Loot: 1…"},{"t":"Forager's Mushroom Stew","at":"the Wolf Den","h":["h5","h17","h8"],"x":"Griffin cooks some Forager's Mushroom Stew in the Wolf Den while the rest pretend to keep watch. It tastes of whatever the woods had going spare.","tag":"camp","k":"meal","id":"m22","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Toasted Cheese Trenchers","at":"the Ashveil Crypts","h":["h18"],"x":"A quiet night in the Ashveil Crypts. Morgan cooks Toasted Cheese Trenchers, eats them slowly and watches the sparks go up. They bubble brown at the corners.","tag":"camp","k":"meal","id":"m23","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"\"The Green Sleeve\" by the fire","at":"camp in Cragtooth Warren","h":["h13","h2"],"x":"Cade hits the high note in \"The Green Sleeve\" and something cracks, possibly the note. Andrew loses all composure.","tag":"song","k":"night","id":"n15","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"the Heron Ford","at":"the road between The Greenwood and Thornwall","h":["h7"],"x":"Corrine crosses the Heron Ford slowly, because the water is clear enough to show exactly how deep it is.","k":"road","id":"r20","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"the Heron Ford","at":"the road between The Greenwood and Thornwall","h":["h7"],"x":"Corrine reaches the Heron Ford and finds the heron on its usual stone, as still as a carving and twice as smug.","k":"road","id":"r21","d":21,"s":1,"sd":21,"imp":1,"score":10},{"t":"Met Brother Aldo","at":"the road between Ashfen and The Ashveil Crypts","h":["h18"],"x":"Brother Aldo tells Morgan he has been to forty shrines this year, and names every one of them, slowly.","k":"road","id":"r13","d":20,"s":1,"sd":20,"imp":3,"score":30},{"t":"Perch, 29 cm","at":"the Thornwall millpond","h":["h7"],"x":"The books show no Perch until today, when Corrine lands one at the Thornwall millpond.","k":"catch","id":"c3","d":20,"s":1,"sd":20,"imp":2,"score":20},{"t":"The Royal Shadows vs 3 Giant Bats and a Kobold","r":"won","at":"Cragtooth Warren","h":["h9","h13","h11","h2"],"tag":"dungeon","k":"fight","id":"f58","d":20,"s":1,"sd":20,"imp":2,"score":20,"x":"In the bat roost on the first floor of Cragtooth Warren, the Royal Shadows square up to 3 Giant Bats and a Kobold and carry the day. Three giant bats went down together, and they have Cade's Volley…"},{"t":"the Mile-Warden's hut","at":"the road between Ironhaven and Thornwall","h":["h7"],"x":"Corrine reports a fallen sign on the road to Thornwall to Sergeant Pellam at the Mile-Warden's hut. The sergeant thanks her and promises it will be fixed by the weekend, a promise Corrine chooses to…","k":"road","id":"r15","d":20,"s":1,"sd":20,"imp":2,"score":20},{"t":"Nothing bit","at":"the King's Road ford","h":["h16","h4"],"x":"The lantern burns low at the King's Road ford and nothing takes the line.","k":"catch","id":"c4","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Drake Steak","h":["h7"],"x":"The market in Ironhaven has a drake cook in today. Corrine queues for a Drake Steak on the strength of the smell alone. It sizzles on the plate long after the fire's out. (3 silver 6 copper)","tag":"tavern","k":"meal","id":"m18","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Wolf Stew","h":["h7"],"x":"Corrine has some Wolf Stew at The Sagging Beam, slowly, with the door open to the street. It keeps everyone warm all night. (2 silver 1 copper)","tag":"tavern","k":"meal","id":"m19","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Ration-Bag Hash","at":"the Wolf Den","h":["h5","h17","h8"],"x":"Griffin cooks some Ration-Bag Hash in the Wolf Den and hands Troy the biggest bowl without a word. It crisps at the edges where the skillet was hottest.","tag":"camp","k":"meal","id":"m20","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Fireside Flatbread","at":"Frostspire","h":["h15"],"x":"Alone in Frostspire, Matt tries a Fireside Flatbread and finds out why people cook it in company: someone has to stop you.","tag":"camp","k":"meal","id":"m21","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"\"Somebody Packed a Chess Set\" by the fire","at":"camp in The Ashveil Crypts","h":["h14"],"x":"Mark sings a song of their own to the fire. The fire is a forgiving audience. Biscuit yawns, loudly, in the second verse.","tag":"song","k":"night","id":"n13","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"\"The Bridge Is Falling\" by the fire","at":"camp in Cragtooth Warren","h":["h1"],"x":"Harry picks out \"The Bridge Is Falling\" on the Fine Lute, every note round and warm as the fire. Nugget's tail thumps the ground in something close to time.","tag":"song","k":"night","id":"n14","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"the Shrine of Quiet Names","at":"the road between Ashfen and The Ashveil Crypts","h":["h18"],"x":"Morgan leaves 1 copper beside a row of stubs at the Shrine of Quiet Names and lights one more.","k":"road","id":"r14","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"the Mile-Warden's hut","at":"the road between Ironhaven and Thornwall","h":["h7"],"x":"Sergeant Pellam gives Corrine the road report at the Mile-Warden's hut: three potholes, one bandit rumoured and a very rude goose.","k":"road","id":"r16","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"On the road","at":"the road between Ashfen and The Ashveil Crypts","h":["h10","h14","h3"],"x":"Olivia finds a small page in the king's livery wandering the road to the Ashveil Crypts, quite lost. Olivia walks the page to the right road, and the page swears to put in a word.","k":"road","id":"r17","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"the Shrine of Quiet Names","at":"the road between Ashfen and The Ashveil Crypts","h":["h10","h14","h3"],"x":"Olivia drops 1 copper in the dish at the Shrine of Quiet Names and lights a taper for the dead of Ashfen.","k":"road","id":"r18","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"the Lakeside Lamprey","at":"the road between The King's Road and Thornwall","h":["h16","h4"],"x":"Allie sits on the porch of the Lakeside Lamprey with a borrowed line and gets one bite and a lot of advice.","k":"road","id":"r19","d":20,"s":1,"sd":20,"imp":1,"score":10},{"t":"Met the Lantern Lady of Gallows Cross","at":"the road between Ironhaven and Thornwall","h":["h7"],"x":"'Which road do you mean to take?' asks the Lantern Lady of Gallows Cross. She draws a card from nowhere and turns it face up for Corrine to read.","k":"road","id":"r11","d":19,"s":1,"sd":19,"imp":3,"score":30},{"t":"Met Marigold","at":"the road between Hollowood and Thornwall","h":["h16","h4"],"x":"Marigold sets up the pot for supper. Katie is given the spoon to hold, and the smell makes the miles ahead seem short.","k":"road","id":"r7","d":19,"s":1,"sd":19,"imp":3,"score":30},{"t":"Met Ines","at":"the road between Ashfen and Carrbridge","h":["h10","h14","h3"],"x":"Ines has drawn a road that does not exist, and is thrilled by it. Ryan gently points out the hedge where it should be.","k":"road","id":"r8","d":19,"s":1,"sd":19,"imp":3,"score":30},{"t":"The Pack of Carrbridge vs 3 Wolves","r":"won","at":"The King's Road","h":["h4","h16"],"tag":"road","k":"fight","id":"f54","d":19,"s":1,"sd":19,"imp":2,"score":20,"x":"The Pack of Carrbridge gets the better of 3 Wolves on the road to Thornwall. The wolf took Katie's Cleave full on and was never the same after. Allie's Frost Shard did the damage (2 times). Loot: 2…"},{"t":"Tidal Riders vs 4 Wolves","r":"won","at":"The Wolf Den","h":["h17","h8","h5"],"tag":"dungeon","k":"fight","id":"f55","d":19,"s":1,"sd":19,"imp":2,"score":20,"x":"It's 4 Wolves against Tidal Riders in the bone yard on floor 1 of the Wolf Den, and it isn't close. The last wolf turns tail. Griffin's Battle Cry had everyone hitting harder. Troy kept them off…"},{"t":"Wolf Stew","at":"the Wolf Den","h":["h5","h17","h8"],"x":"Supper in the Wolf Den is some Wolf Stew. Griffin pretends not to watch everyone's faces. It is wolf, which nobody mentions to the horses.","tag":"camp","k":"meal","id":"m17","d":19,"s":1,"sd":19,"imp":2,"score":20},{"t":"Tidal Riders vs 2 Wolves and a Dire Wolf","r":"won","at":"The Wolf Den","h":["h17","h8","h5"],"tag":"dungeon","k":"fight","id":"f56","d":19,"s":1,"sd":19,"imp":1,"score":10,"x":"Amanda hits hardest as Tidal Riders dispatch 2 Wolves and a Dire Wolf in the lookout log on floor 1 of the Wolf Den. Troy's Phantasm landed on the wolf at the right moment. Amanda accounted for 3 of…"},{"t":"Tidal Riders vs 3 Wolves","r":"won","at":"The Wolf Den","h":["h17","h8","h5"],"tag":"dungeon","k":"fight","id":"f57","d":19,"s":1,"sd":19,"imp":1,"score":10,"x":"Tidal Riders make short work of 3 Wolves in the hunting ground on floor 1 of the Wolf Den. Amanda spoke the words of Drain Life, and the wolf fell where it stood. Griffin's Battle Cry turned the…"},{"t":"Varro Brothers' Spiced Bun","at":"judging the Ironhaven cooks' feud","h":["h7"],"x":"Corrine is cornered by Aldo Varro and Benno Varro in Ironhaven and made to taste both. Benno Varro wins, and Aldo Varro demands a recount. (6 copper)","tag":"tavern","k":"meal","id":"m15","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"The Collegium Trifle","h":["h7"],"x":"Corrine spots The Collegium Trifle on the board at The Gilded Flagon and doesn't even sit down before ordering. Her favourite kind of thing. (1 silver 8 copper)","tag":"tavern","k":"meal","id":"m16","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Checkers: Cade v Andrew","at":"camp in Cragtooth Warren","h":["h13","h2"],"x":"Four jumps in a single turn, and the match belongs to Cade. Cade and Andrew start a record tonight, and both swear it will be short. Andrew pays the debt in blisters and shoulder straps.","tag":"checkers","k":"night","id":"n12","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"the Last Dry Sock","at":"the road between Cragtooth Warren and Ironhaven","h":["h11","h13","h2","h9"],"x":"The Last Dry Sock's stew has a name, a reputation and a regular complaint. Keenan buys a bowl for 1 silver and finds the complaint is justified and the stew excellent.","k":"road","id":"r10","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"the Leaning Mile","at":"the road between Ashfen and Carrbridge","h":["h18"],"x":"Morgan finds a clear patch on the back of the Leaning Mile and carves a name there, small and straight against the lean.","k":"road","id":"r12","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"the Leaning Mile","at":"the road between Ashfen and Carrbridge","h":["h10","h14","h3"],"x":"Ryan reads the distances on the Leaning Mile and gets a different sum each way. The stone has leaned so far that it counts from the side.","k":"road","id":"r9","d":19,"s":1,"sd":19,"imp":1,"score":10},{"t":"Golden Carp, 47 cm","at":"by a stream on the road to Thornwall","h":["h16","h4"],"x":"Katie lands a Golden Carp by a stream on the road to Thornwall, the first the league has ever seen. The anglers will want to hear about it.","k":"catch","id":"c1","d":18,"s":1,"sd":18,"imp":2,"score":20},{"t":"Matt vs a Frost Wolf and an Ice Wraith","r":"won","at":"Frostspire","h":["h15"],"tag":"dungeon","k":"fight","id":"f51","d":18,"s":1,"sd":18,"imp":2,"score":20,"x":"Matt dispatches a Frost Wolf and an Ice Wraith on floor 1 of Frostspire. The frost wolf went down to Matt's Power Strike. Loot: 5 pelts."},{"t":"The Royal Shadows vs 4 Wolves","r":"won","at":"The King's Road","h":["h9","h13","h11","h2"],"tag":"road","k":"fight","id":"f52","d":18,"s":1,"sd":18,"imp":2,"score":20,"x":"The Royal Shadows cut down 4 Wolves on the road to Ironhaven. The last wolf bolts. The wolf had been trouble right up until Keenan's Frost Shard. Andrew found the weak spot first and kept hitting…"},{"t":"The Green Hammers vs 2 Cave Slimes","r":"won","at":"Cragtooth Warren","h":["h1","h12"],"tag":"dungeon","k":"fight","id":"f53","d":18,"s":1,"sd":18,"imp":2,"score":20,"x":"The Green Hammers cut down 2 Cave Slimes on floor 2 of Cragtooth Warren. Somewhere around Jeff's Thorn Whip, the other side stopped believing. Jeff landed 2 crushing blows, mostly with Aimed Shot.…"},{"t":"Cards for Mark, read by Sabine Venn","at":"the toll-house parlour","h":["h14"],"x":"Sabine Venn lays three cards out for Mark at the toll-house parlour: the Six of Swords, the Ten of Cups and the Two of Swords. Sabine Venn says it could go either way.","k":"reading","id":"r6","d":18,"s":1,"sd":18,"imp":2,"score":20},{"t":"Nothing bit","at":"by a stream on the road to Ironhaven","h":["h7"],"x":"Something moves in the dark by a stream on the road to Ironhaven, but it is not on the hook. Corrine decides that is fine.","k":"catch","id":"c2","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Troll Haunch","h":["h13"],"x":"Cade has a Troll Haunch at The Gilded Flagon and sends compliments to Madame Ostrava. It has to be carved faster than it heals. (2 silver 7 copper)","tag":"tavern","k":"meal","id":"m13","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Trail Porridge with Honey","at":"Cragtooth Warren","h":["h1","h12"],"x":"Harry stirs, tastes, frowns, adds salt in Cragtooth Warren, and serves some Trail Porridge with Honey. It tastes like a promise that tomorrow will happen.","tag":"camp","k":"meal","id":"m14","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"\"Inga's Third Coat\" by the fire","at":"camp in The Wolf Den","h":["h8"],"x":"Troy sings \"Inga's Third Coat\" by the fire. Nobody joins in, but nobody stops them either.","tag":"song","k":"night","id":"n10","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Checkers: Andrew v Keenan","at":"The Gilded Flagon","h":["h2","h9"],"x":"Checkers on the log tonight, and Keenan insists the flat side of it is lucky. Andrew loses at checkers and says the board was uneven, though it was not. Keenan and Andrew play for the first time,…","tag":"checkers","k":"night","id":"n11","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Chess: Ryan v Mark","at":"camp by the road to Ashfen","h":["h3","h14"],"x":"Ryan gives the queen away for nothing on move 20, and the camp gasps. Down a queen, Ryan resigns on move 22 with good grace. Mark and Ryan shake hands over the Academy Ivory Chess, and the tally…","tag":"chess","k":"night","id":"n9","d":18,"s":1,"sd":18,"imp":1,"score":10},{"t":"Cards for Morgan, read by Sabine Venn","at":"the toll-house parlour","h":["h18"],"x":"At the toll-house parlour, Sabine Venn turns Morgan's three cards one at a time: the Five of Pentacles upside down, the Queen of Cups and the Sun. A good spread, all told.","k":"reading","id":"r4","d":17,"s":1,"sd":17,"imp":2,"score":20},{"t":"Thornwall Meat Pie","at":"judging the Thornwall cooks' feud","h":["h18"],"x":"Morgan is cornered by Goodwife Pell of the guild bakehouse and Corporal Hobb of the barracks kitchen in Thornwall and made to taste both. Corporal Hobb of the barracks kitchen wins, and Goodwife…","tag":"tavern","k":"meal","id":"m10","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Kobold Peppercorn Stew","h":["h18"],"x":"Jolly Mott talks Morgan into some Kobold Peppercorn Stew at The Honest Toll. Good advice: it is eaten slowly and with respect. (2 silver 1 copper)","tag":"tavern","k":"meal","id":"m11","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Ration-Bag Hash","at":"Cragtooth Warren","h":["h1","h12"],"x":"Harry's Ration-Bag Hash in Cragtooth Warren goes wrong somewhere between the pot and the plate. Nobody can say where, but everyone can say when.","tag":"camp","k":"meal","id":"m12","d":17,"s":1,"sd":17,"imp":1,"score":10},{"t":"Corrine's first reading, from Aunt Crumb at the back of the pie shop: three…","h":["h7"],"k":"reading","id":"r5","d":17,"s":1,"sd":17,"imp":1,"score":10,"x":"Corrine's first reading, from Aunt Crumb at the back of the pie shop: three cards, and Aunt Crumb taps the Lovers twice."},{"t":"The Sergeant's Roast","h":["h17"],"x":"Old Hesk has written The Sergeant's Roast on the board at The Sagging Beam in letters a foot high: dish of the week. Amanda orders it before sitting down. It is carved at attention. (3 silver)","tag":"tavern","k":"meal","id":"m5","d":16,"s":1,"sd":16,"imp":2,"score":20},{"t":"The Sergeant's Roast","h":["h5"],"x":"Griffin has The Sergeant's Roast at The Sagging Beam and sends compliments to Old Hesk. It comes with the carving shouted out slice by slice. (3 silver)","tag":"tavern","k":"meal","id":"m6","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Smoked Ice-Lake Salmon","at":"the Frosthold feast-day tables","h":["h15"],"x":"Feast day in Frosthold: Matt finds a bench at the long tables and eats some Smoked Ice-Lake Salmon with strangers who are friends by the pudding. It tastes of birch smoke and a cold clear lake. (8…","tag":"tavern","k":"meal","id":"m7","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Forge-Bellows Pepper Pot","h":["h14"],"x":"Madame Ostrava has written Forge-Bellows Pepper Pot on the board at The Gilded Flagon in letters a foot high: dish of the week. Mark orders it before sitting down. It has a ladle that has never been…","tag":"tavern","k":"meal","id":"m8","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Twist-Bread on a Stick","at":"Cragtooth Warren","h":["h1","h12"],"x":"Harry tries some Twist-Bread on a Stick in Cragtooth Warren. It goes wrong in a way nobody can quite explain, and everyone is a little unwell by morning.","tag":"camp","k":"meal","id":"m9","d":16,"s":1,"sd":16,"imp":1,"score":10},{"t":"Cards for Matt, read by Grandmother Skaldi","at":"a hut at the edge of the snowfield","h":["h15"],"x":"Grandmother Skaldi lays three cards out for Matt at a hut at the edge of the snowfield: the Ten of Pentacles, the Ace of Pentacles and the Knight of Swords. The cards are kind.","k":"reading","id":"r1","d":15,"s":1,"sd":15,"imp":2,"score":20},{"t":"Sabine Venn lays out Harry's first spread at the toll-house parlour. \"The Ten…","h":["h1"],"k":"reading","id":"r2","d":15,"s":1,"sd":15,"imp":2,"score":20,"x":"Sabine Venn lays out Harry's first spread at the toll-house parlour. \"The Ten of Swords upside down,\" Sabine Venn says, and lets it sit there."},{"t":"Thornwall Meat Pie","h":["h16"],"x":"Thornwall Meat Pie, eaten on a Thornwall doorstep by Katie, who refuses to share. It has a crust that would hold back a siege, and the gravy behind it. (1 silver)","tag":"tavern","k":"meal","id":"m4","d":15,"s":1,"sd":15,"imp":1,"score":10},{"t":"Tidal Riders vs Gruk the Warchief, a Goblin Shaman and a Goblin","r":"won","at":"Goblin Camp","h":["h17","h8","h5"],"tag":"dungeon","k":"fight","id":"f41","d":14,"s":1,"sd":14,"imp":5,"score":173,"x":"At the bottom of Goblin Camp, Tidal Riders slay Gruk the Warchief, a Goblin Shaman and a Goblin. Amanda found the weak spot first and kept hitting it; without Griffin's Battle Cry, this goes…"},{"t":"The Royal Shadows vs 3 Kobolds","r":"won","at":"Cragtooth Warren","h":["h9","h13","h11","h2"],"tag":"camp","k":"fight","id":"f46","d":14,"s":1,"sd":14,"imp":3,"score":30,"x":"In the middle of the night, The Royal Shadows make short work of 3 Kobolds at their camp in Cragtooth Warren. Cade kept a cool head while everyone else was shouting, and Andrew and Socks the dog…"},{"t":"Gruk's Victory Ham","at":"Goblin Camp","h":["h5","h17","h8"],"x":"Griffin cooks Gruk's Victory Ham in Goblin Camp, from the spoils. Nobody says a word until it's gone. It is the best thing Gruk ever owned. They'll talk about it for years.","tag":"legendary","k":"meal","id":"m2","d":14,"s":1,"sd":14,"imp":3,"score":30},{"t":"Spice-Barge Pilaf","h":["h4"],"x":"Allie has some Spice-Barge Pilaf at The Honest Toll and sends compliments to Jolly Mott. It has a raisin in every third mouthful, by tradition. (2 silver)","tag":"tavern","k":"meal","id":"m1","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"Kobold Peppercorn Stew","h":["h1"],"x":"Harry spots some Kobold Peppercorn Stew on the board at The Honest Toll and doesn't even sit down before ordering. His favourite kind of thing. (2 silver 1 copper)","tag":"tavern","k":"meal","id":"m3","d":14,"s":1,"sd":14,"imp":1,"score":10},{"t":"The Royal Shadows vs 2 Bandit Archers, a Bandit Captain and a Bandit","r":"won","at":"The King's Road","h":["h9","h13","h11","h2"],"tag":"road","k":"fight","id":"f39","d":13,"s":1,"sd":13,"imp":3,"score":30,"x":"The Royal Shadows handle 2 Bandit Archers, a Bandit Captain and a Bandit on the road to Cragtooth Warren. Whenever it looked bad, Andrew was already there. Joshua picked the biggest one and did not…"},{"t":"Morgan vs a Bandit","r":"won","at":"The Greenwood","h":["h18"],"tag":"road","k":"fight","id":"f35","d":12,"s":1,"sd":12,"imp":3,"score":30,"x":"First blood for Morgan: Morgan sees off a Bandit on the road to the Greenwood. Loot: 3 rations."},{"t":"Matt vs the Silk Matriarch","r":"won","at":"The Collapsed Mine","h":["h15"],"tag":"dungeon","k":"fight","id":"f29","d":11,"s":1,"sd":11,"imp":5,"score":137,"x":"Matt slays the Silk Matriarch at the bottom of the Collapsed Mine. Loot: 11 chitin."},{"t":"Tidal Riders vs 4 Goblins and a Giant Rat","r":"won","at":"Goblin Camp","h":["h17","h8","h5"],"tag":"dungeon","k":"fight","id":"f31","d":11,"s":1,"sd":11,"imp":3,"score":30,"x":"First blood for Amanda and Griffin: Tidal Riders handle 4 Goblins and a Giant Rat on floor 1 of Goblin Camp. Whenever it looked bad, Amanda was already there. Loot: 5 goblin ears."},{"t":"The Royal Shadows vs 5 Wolves","r":"won","at":"The King's Road","h":["h9","h13","h11","h2"],"k":"fight","id":"f24","d":9,"s":1,"sd":9,"imp":3,"score":30,"x":"The Royal Shadows defeat 5 Wolves on the King's Road, with Cade calling out every flank before it turned. Loot: 3 pelts, 3 fangs & claws."},{"t":"The Green Hammers vs a Drake, a Cliff Crab and a Bandit","r":"won","at":"The Salt Cliffs","h":["h1","h12"],"k":"fight","id":"f17","d":8,"s":1,"sd":8,"imp":3,"score":30,"x":"First blood for Harry: The Green Hammers beat a Drake, a Cliff Crab and a Bandit on the road to the Salt Cliffs, and Harry went in first without waiting to be asked. Jeff is already telling it as…"},{"t":"The Pack of Carrbridge vs a Bandit Captain, a Wolf and a Bandit Archer","r":"won","at":"The King's Road","h":["h4","h16"],"k":"fight","id":"f20","d":8,"s":1,"sd":8,"imp":3,"score":30,"x":"First blood for Allie and Katie: The Pack of Carrbridge routs a Bandit Captain, a Wolf and a Bandit Archer on the King's Road and comes away with 6 stolen goods and 1 fang."},{"t":"The Black Pack vs 2 Bandits","r":"won","at":"The King's Road","h":["h14","h3","h10"],"k":"fight","id":"f21","d":8,"s":1,"sd":8,"imp":3,"score":30,"x":"First blood for Mark, Ryan and Olivia: The Black Pack sees off 2 Bandits on the King's Road. Loot: 4 stolen goods, 1 ration, 1 trinket."},{"t":"Tidal Riders vs 2 Bandit Captains","r":"lost","at":"The King's Road","h":["h17","h8"],"k":"fight","id":"f16","d":6,"s":1,"sd":6,"imp":3,"score":30,"x":"Two Bandit Captains rout the Tidal Riders on the King's Road, and Amanda and Troy beat a hasty retreat. \"Run! Why aren't we running?\" Troy asks, already running."},{"t":"The Royal Shadows vs a Wolf, a Bandit Archer and a Bandit","r":"won","at":"The King's Road","h":["h9","h13","h11"],"k":"fight","id":"f11","d":4,"s":1,"sd":4,"imp":3,"score":30,"x":"First blood for Keenan: The Royal Shadows see off a Wolf, a Bandit Archer and a Bandit on the King's Road. Joshua did the unglamorous work that kept the line from breaking. Loot: 1 fang, 2 stolen…"},{"t":"Jeff vs a Bandit","r":"won","at":"The King's Road","h":["h12"],"k":"fight","id":"f13","d":4,"s":1,"sd":4,"imp":3,"score":30,"x":"First blood for Jeff: one Bandit, beaten on the road to Veldrock. The spoils: 1 ration."},{"t":"Joshua vs Mother Mire","r":"lost","at":"The King's Road","h":["h11"],"k":"fight","id":"f8","d":3,"s":1,"sd":3,"imp":3,"score":30,"x":"Mother Mire overwhelms Joshua on the King's Road. He comes away with a broken leg."},{"t":"Troy vs a Wolf","r":"won","at":"The King's Road","h":["h8"],"k":"fight","id":"f3","d":2,"s":1,"sd":2,"imp":3,"score":30,"x":"First blood for Troy: he sees off a Wolf on the road to Thornwall and walks away with 1 pelt and 2 fangs & claws."},{"t":"Andrew vs a Bandit Archer and a Bandit","r":"won","at":"The King's Road","h":["h2"],"k":"fight","id":"f4","d":2,"s":1,"sd":2,"imp":3,"score":30,"x":"First blood for Andrew, on the King's Road: a Bandit Archer and a Bandit go down, and he comes away with 1 bag of stolen goods."},{"t":"Matt vs a Giant Rat and a Kobold","r":"won","at":"The Collapsed Mine","h":["h15"],"k":"fight","id":"f5","d":2,"s":1,"sd":2,"imp":3,"score":30,"x":"First blood for Matt, on floor 1 of the Collapsed Mine: a Giant Rat and a Kobold, dispatched. The haul: 1 fang and 1 trinket."},{"t":"Cade vs a Bandit Archer","r":"won","at":"The King's Road","h":["h13"],"k":"fight","id":"f6","d":2,"s":1,"sd":2,"imp":3,"score":30,"x":"First blood for Cade: he makes short work of a Bandit Archer on the road to Ironhaven and pockets 1 bag of stolen goods."},{"t":"Keenan vs a Bandit Captain","r":"lost","at":"The King's Road","h":["h9"],"k":"fight","id":"f7","d":2,"s":1,"sd":2,"imp":3,"score":30,"x":"A Bandit Captain catches Keenan on the road to Ironhaven, and Keenan does the sensible thing: he runs for it."},{"t":"Mark vs a Bandit Captain and a Wolf","r":"lost","at":"The King's Road","h":["h14"],"k":"fight","id":"f1","d":1,"s":1,"sd":1,"imp":3,"score":30,"x":"A rough start on the road to Veldrock: a Bandit Captain and a Wolf overwhelm Mark, who limps off with a cracked collarbone."}]};